SELECT s.asset_type,s.equity_category,s.isin,s.symbol,s.series,s.name,s.description,s.exchange,s.currency,s.country,s.market,s.risk_level,s.status
FROM tmp_asset_seed s
LEFT JOIN security_details existing ON existing.symbol=s.symbol
WHERE existing.security_id IS NULL;

WITH RECURSIVE calendar(trade_date) AS (
  SELECT DATE('2024-09-30')
  UNION ALL
  SELECT trade_date + INTERVAL 1 DAY FROM calendar WHERE trade_date < DATE('2026-09-25')
),
sessions AS (
  SELECT trade_date FROM calendar WHERE WEEKDAY(trade_date) < 5
),
targets AS (
  SELECT sd.security_id, sd.symbol, sd.asset_type, COALESCE(sd.equity_category,'') AS equity_category,
    CASE
      WHEN sd.asset_type='CASH' AND sd.symbol='INR' THEN 1.0
      WHEN sd.asset_type='CASH' AND sd.symbol='USD' THEN 83.0
      WHEN sd.asset_type='CASH' AND sd.symbol='EUR' THEN 91.0
      WHEN sd.asset_type='CASH' AND sd.symbol='GBP' THEN 106.0
      WHEN sd.asset_type='CASH' AND sd.symbol='JPY' THEN 0.56
      WHEN sd.asset_type='MUTUAL' THEN 10.0 + MOD(CRC32(sd.symbol),500000)/10000.0
      WHEN sd.asset_type='BOND' THEN 90.0 + MOD(CRC32(sd.symbol),2000)/100.0
      WHEN sd.asset_type='COMMODITY' AND sd.symbol LIKE '%GOLD%' THEN 70000.0
      WHEN sd.asset_type='COMMODITY' AND sd.symbol LIKE '%SILVER%' THEN 800.0
      WHEN sd.asset_type='COMMODITY' THEN 50.0 + MOD(CRC32(sd.symbol),50000)/100.0
      WHEN sd.asset_type='CRYPTO' THEN 100.0 + MOD(CRC32(sd.symbol),1000000)/100.0
      WHEN sd.asset_type='CASH' THEN 1.0 + MOD(CRC32(sd.symbol),50000)/10000.0
      ELSE 20.0 + MOD(CRC32(sd.symbol),300000)/100.0
    END AS base_price,
    CASE
      WHEN sd.asset_type='EQUITY' AND sd.equity_category='SMALL_CAP' THEN 0.027
      WHEN sd.asset_type='EQUITY' AND sd.equity_category='MID_CAP' THEN 0.021
      WHEN sd.asset_type='EQUITY' THEN 0.016
      WHEN sd.asset_type='CRYPTO' THEN 0.048
      WHEN sd.asset_type='COMMODITY' THEN 0.024
      WHEN sd.asset_type='REIT' THEN 0.014
      WHEN sd.asset_type='ETF' THEN 0.013
      WHEN sd.asset_type='MUTUAL' THEN 0.008
      WHEN sd.asset_type='BOND' THEN 0.0025
      ELSE 0.001
    END AS volatility
  FROM security_details sd
  INNER JOIN tmp_asset_seed seed ON seed.symbol=sd.symbol
  WHERE sd.status='ACTIVE' AND sd.symbol <> 'RELIANCE'
),
returns AS (
  SELECT t.security_id,t.symbol,t.asset_type,t.base_price,t.volatility,d.trade_date,
    ((SIN(MOD(CRC32(t.symbol),1000000)/1000000.0 + TO_DAYS(d.trade_date)*0.017)
      + COS(MOD(CRC32(t.symbol),1000000)/1000000.0 + TO_DAYS(d.trade_date)*0.041)) * t.volatility) AS log_return
  FROM targets t CROSS JOIN sessions d
),
paths AS (
  SELECT security_id,symbol,asset_type,trade_date,
    ROUND(base_price * EXP(SUM(log_return) OVER (PARTITION BY security_id ORDER BY trade_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)),6) AS close_px
  FROM returns
),
lagged AS (
  SELECT security_id,symbol,asset_type,trade_date,close_px,
    COALESCE(LAG(close_px) OVER (PARTITION BY security_id ORDER BY trade_date),close_px) AS prev_px
  FROM paths
),
opened AS (
  SELECT security_id,symbol,asset_type,trade_date,close_px,prev_px,
    ROUND(prev_px * (1 + SIN(TO_DAYS(trade_date)*0.31 + MOD(CRC32(symbol),1000))*0.004),6) AS open_px
  FROM lagged
),
ohlc AS (
  SELECT security_id,symbol,asset_type,trade_date,close_px,prev_px,open_px,
    ROUND(GREATEST(open_px,close_px) * (1 + ABS(COS(TO_DAYS(trade_date)*0.19))*0.004),6) AS high_px,
    ROUND(LEAST(open_px,close_px) * (1 - ABS(SIN(TO_DAYS(trade_date)*0.23))*0.004),6) AS low_px
  FROM opened
)
SELECT security_id,trade_date,open_px,high_px,low_px,close_px,prev_px,close_px,
  1000 + MOD(CRC32(CONCAT(symbol,DATE_FORMAT(trade_date,'%Y%m%d'))),1000000),
  CASE WHEN asset_type='MUTUAL' THEN close_px ELSE NULL END,
  CASE WHEN asset_type='COMMODITY' THEN close_px ELSE NULL END,
  CASE WHEN asset_type='BOND' THEN close_px ELSE NULL END
FROM ohlc;

COMMIT;

DROP TEMPORARY TABLE IF EXISTS tmp_asset_seed;


-- GICS reference rows required by security_details.gics_industry_code.
-- Standard GICS industry lookup rows used by the NSE, LSE and NASDAQ security records.
ON DUPLICATE KEY UPDATE
	sector_code = VALUES(sector_code),
	sector_name = VALUES(sector_name),
	industry_name = VALUES(industry_name);


-- Classify well-known Indian listings with their GICS industry; the remaining catalogue rows stay unclassified until verified.
UPDATE security_details SET gics_industry_code=CASE symbol
  WHEN 'TCS' THEN '451020' WHEN 'INFY' THEN '451020' WHEN 'HCLTECH' THEN '451020' WHEN 'WIPRO' THEN '451020'
  WHEN 'HDFCBANK' THEN '401010' WHEN 'ICICIBANK' THEN '401010' WHEN 'SBIN' THEN '401010' WHEN 'KOTAKBANK' THEN '401010' WHEN 'AXISBANK' THEN '401010'
  WHEN 'BAJFINANCE' THEN '402020' WHEN 'BAJAJFINSV' THEN '402010'
  WHEN 'BHARTIARTL' THEN '501020'
  WHEN 'SUNPHARMA' THEN '352020' WHEN 'DRREDDY' THEN '352020' WHEN 'CIPLA' THEN '352020'
  WHEN 'MARUTI' THEN '251020' WHEN 'TATAMOTORS' THEN '251020'
  WHEN 'ITC' THEN '302030' WHEN 'HINDUNILVR' THEN '303010'
  WHEN 'ASIANPAINT' THEN '151010' WHEN 'TATASTEEL' THEN '151040' WHEN 'ULTRACEMCO' THEN '151020'
  WHEN 'NTPC' THEN '551010' WHEN 'POWERGRID' THEN '551010' WHEN 'HDFCLIFE' THEN '403010'
  ELSE gics_industry_code END
WHERE symbol IN ('TCS','INFY','HCLTECH','WIPRO','HDFCBANK','ICICIBANK','SBIN','KOTAKBANK','AXISBANK','BAJFINANCE','BAJAJFINSV','BHARTIARTL','SUNPHARMA','DRREDDY','CIPLA','MARUTI','TATAMOTORS','ITC','HINDUNILVR','ASIANPAINT','TATASTEEL','ULTRACEMCO','NTPC','POWERGRID','HDFCLIFE');

-- Remove legacy placeholder instruments and duplicate HDFC rows; canonical AMFI MF- scheme records are kept.
DELETE dp FROM daily_prices dp JOIN security_details sd ON sd.security_id=dp.security_id WHERE sd.symbol='REIT5';
DELETE FROM security_details WHERE symbol='REIT5';
DELETE dp FROM daily_prices dp JOIN security_details sd ON sd.security_id=dp.security_id WHERE sd.symbol IN ('SBINBOND','HDFCBOND','PFCBOND','HCLTBOND','RELIANCEBOND');
DELETE FROM security_details WHERE symbol IN ('SBINBOND','HDFCBOND','PFCBOND','HCLTBOND','RELIANCEBOND');
UPDATE security_details SET exchange='MCX' WHERE asset_type='COMMODITY' AND exchange='DEMO';
DELETE dp FROM daily_prices dp JOIN security_details dup ON dup.security_id=dp.security_id JOIN security_details real_mf ON real_mf.asset_type='MUTUAL' AND real_mf.name=dup.name AND real_mf.isin IS NOT NULL WHERE dup.asset_type='MUTUAL' AND dup.isin IS NULL AND dup.symbol IN ('HDFCFLEXICAP','HDFCBALADV','HDFCMIDCAP','HDFCLARGECAP','HDFCMULTICAP');
DELETE dup FROM security_details dup JOIN security_details real_mf ON real_mf.asset_type='MUTUAL' AND real_mf.name=dup.name AND real_mf.isin IS NOT NULL WHERE dup.asset_type='MUTUAL' AND dup.isin IS NULL AND dup.symbol IN ('HDFCFLEXICAP','HDFCBALADV','HDFCMIDCAP','HDFCLARGECAP','HDFCMULTICAP');
UPDATE security_details SET isin=NULL WHERE asset_type='MUTUAL' AND isin LIKE 'INF00XX%';
UPDATE security_details SET name=CASE symbol WHEN 'GOLD' THEN 'Gold (MCX Gold Futures)' WHEN 'SILVER' THEN 'Silver (MCX Silver Futures)' WHEN 'CRUDEOIL' THEN 'Crude Oil (MCX Futures)' WHEN 'NATURALGAS' THEN 'Natural Gas (MCX Futures)' WHEN 'COPPER' THEN 'Copper (MCX Futures)' WHEN 'SBINBOND' THEN 'State Bank of India Corporate Bond' WHEN 'HDFCBOND' THEN 'HDFC Bank Corporate Bond' WHEN 'PFCBOND' THEN 'Power Finance Corporation Corporate Bond' WHEN 'HCLTBOND' THEN 'HCL Technologies Corporate Bond' WHEN 'RELIANCEBOND' THEN 'Reliance Industries Corporate Bond' WHEN 'BTC' THEN 'Bitcoin' WHEN 'ETH' THEN 'Ethereum' WHEN 'BNB' THEN 'BNB (Build and Build)' WHEN 'SOL' THEN 'Solana' WHEN 'XRP' THEN 'XRP' WHEN 'EMBASSY' THEN 'Embassy Office Parks REIT' WHEN 'MINDSPACE' THEN 'Mindspace Business Parks REIT' WHEN 'BIRET' THEN 'Brookfield India Real Estate Trust' WHEN 'NXST' THEN 'Nexus Select Trust' WHEN 'NIFTYBEES' THEN 'Nippon India ETF Nifty 50 BeES' WHEN 'BANKBEES' THEN 'Nippon India ETF Bank BeES' WHEN 'JUNIORBEES' THEN 'Nippon India ETF Nifty Next 50 Junior BeES' WHEN 'GOLDBEES' THEN 'Nippon India ETF Gold BeES' WHEN 'ITBEES' THEN 'Nippon India ETF Nifty IT' ELSE name END WHERE symbol IN ('GOLD','SILVER','CRUDEOIL','NATURALGAS','COPPER','SBINBOND','HDFCBOND','PFCBOND','HCLTBOND','RELIANCEBOND','BTC','ETH','BNB','SOL','XRP','EMBASSY','MINDSPACE','BIRET','NXST','NIFTYBEES','BANKBEES','JUNIORBEES','GOLDBEES','ITBEES');

-- Add 1,250 AMFI Direct Growth schemes and 1,708 active NSE debt listings (2,958 total).
-- Metadata is sourced from official AMFI and NSE catalogs; only price paths below are synthetic.
DROP TEMPORARY TABLE IF EXISTS tmp_5000_asset_seed;
CREATE TEMPORARY TABLE tmp_5000_asset_seed (
 asset_type VARCHAR(20) NOT NULL,equity_category VARCHAR(30) NULL,isin VARCHAR(12) NULL,symbol VARCHAR(50) NOT NULL,
 series VARCHAR(10) NULL,name VARCHAR(200) NOT NULL,description VARCHAR(500) NULL,exchange VARCHAR(30) NULL,currency VARCHAR(10) NULL,
 country VARCHAR(100) NULL,market VARCHAR(100) NULL,risk_level VARCHAR(30) NULL,status VARCHAR(20) NOT NULL,
 PRIMARY KEY (symbol),UNIQUE KEY uq_tmp_5000_isin (isin)
) ENGINE=InnoDB;
SELECT seed.asset_type,seed.equity_category,seed.isin,seed.symbol,seed.series,seed.name,seed.description,seed.exchange,seed.currency,seed.country,seed.market,seed.risk_level,seed.status
FROM tmp_5000_asset_seed seed
LEFT JOIN security_details existing ON existing.symbol=seed.symbol OR existing.isin=seed.isin
WHERE existing.security_id IS NULL;
WITH RECURSIVE calendar(trade_date) AS (
 SELECT DATE('2024-09-30') UNION ALL SELECT trade_date + INTERVAL 1 DAY FROM calendar WHERE trade_date < DATE('2026-09-25')
), sessions AS (SELECT trade_date FROM calendar WHERE WEEKDAY(trade_date)<5), targets AS (
 SELECT sd.security_id,sd.symbol,sd.asset_type,
  CASE WHEN sd.asset_type='MUTUAL' THEN 10.0+MOD(CRC32(sd.symbol),500000)/10000.0
       WHEN sd.asset_type='BOND' THEN 90.0+MOD(CRC32(sd.symbol),2000)/100.0 END AS base_price,
  CASE WHEN sd.asset_type='MUTUAL' THEN 0.008 ELSE 0.0025 END AS volatility
 FROM security_details sd JOIN tmp_5000_asset_seed seed ON seed.symbol=sd.symbol AND seed.isin=sd.isin
 WHERE sd.status='ACTIVE' AND NOT EXISTS (SELECT 1 FROM daily_prices existing_price WHERE existing_price.security_id=sd.security_id)
), returns AS (
 SELECT t.security_id,t.symbol,t.asset_type,t.base_price,t.volatility,d.trade_date,
 ((SIN(MOD(CRC32(t.symbol),1000000)/1000000.0+TO_DAYS(d.trade_date)*0.017)
 +COS(MOD(CRC32(t.symbol),1000000)/1000000.0+TO_DAYS(d.trade_date)*0.041))*t.volatility) AS log_return
 FROM targets t CROSS JOIN sessions d
), paths AS (
 SELECT security_id,symbol,asset_type,trade_date,
  ROUND(base_price*EXP(SUM(log_return) OVER(PARTITION BY security_id ORDER BY trade_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)),6) AS close_px
 FROM returns
), lagged AS (
 SELECT security_id,symbol,asset_type,trade_date,close_px,
  COALESCE(LAG(close_px) OVER(PARTITION BY security_id ORDER BY trade_date),close_px) AS prev_px FROM paths
), opened AS (
 SELECT security_id,symbol,asset_type,trade_date,close_px,prev_px,
  ROUND(prev_px*(1+SIN(TO_DAYS(trade_date)*0.31+MOD(CRC32(symbol),1000))*0.004),6) AS open_px FROM lagged
), ohlc AS (
 SELECT security_id,symbol,asset_type,trade_date,close_px,prev_px,open_px,
  ROUND(GREATEST(open_px,close_px)*(1+ABS(COS(TO_DAYS(trade_date)*0.19))*0.004),6) AS high_px,
  ROUND(LEAST(open_px,close_px)*(1-ABS(SIN(TO_DAYS(trade_date)*0.23))*0.004),6) AS low_px FROM opened
)
SELECT security_id,trade_date,open_px,high_px,low_px,close_px,prev_px,close_px,
  1000+MOD(CRC32(CONCAT(symbol,DATE_FORMAT(trade_date,'%Y%m%d'))),1000000),
  CASE WHEN asset_type='MUTUAL' THEN close_px END,NULL,NULL FROM ohlc;
DROP TEMPORARY TABLE IF EXISTS tmp_5000_asset_seed;

-- Expanded-catalog verification summary.
SELECT asset_type,COALESCE(equity_category,'-') AS category,COUNT(*) AS asset_count
FROM security_details GROUP BY asset_type,equity_category ORDER BY asset_type,category;
SELECT COUNT(*) AS generated_price_rows,MIN(trade_date) AS first_date,MAX(trade_date) AS last_date,COUNT(DISTINCT security_id) AS priced_assets FROM daily_prices;